import json,re
from pathlib import Path
from html import escape as E
from emblem_options import build_options
P=Path(__file__).resolve().parent
BADGES={'105':'需森转','114':'需迅射转','112':'需火转','115':'需宝宝学院','116':'需裁决进化'}
STYLES={'104':'赌1费','107':'赌1费','110':'赌1费','115':'赌1费','87':'赌2费','100':'赌2费','106':'赌2费','99':'赌3费','116':'赌3费','105':'上8','114':'上8','112':'上9','113':'上9','89':'上9'}
CSS='''
.tab-badges{display:flex;gap:4px;align-items:center}.tab-style{font-size:10px;line-height:15px;border-radius:3px;padding:0 4px;background:#dce9f3;color:#31566d}.tab-list button[aria-selected="true"] .tab-style{background:#e1eef6;color:#31566d}.hf-switch{display:flex;align-items:center;gap:7px;min-height:44px;font-size:14px;font-weight:600;margin:7px 0;cursor:pointer}.hf-switch input{accent-color:#176d67;width:17px;height:17px;flex:none}.tab-list button{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;padding:2px 5px;line-height:19px}.tab-condition{font-size:10px;line-height:15px;border-radius:3px;background:#f2e0ba;color:#70480c;padding:0 4px;white-space:nowrap}.tab-list button[aria-selected="true"] .tab-condition{background:#fff0cf;color:#70480c}.hex-filter{border:1px solid #cddbd3;border-radius:7px;padding:0 10px;margin:9px 0;background:#fff}.hex-filter>summary{font-size:14px;padding:10px 0;min-height:44px;font-weight:600}.hf-note{font-size:12px;color:#647168;line-height:1.6;margin:5px 0 9px}.hf-toolbar{display:flex;gap:7px;margin:9px 0}.hf-toolbar input{min-width:0;flex:1;font:inherit;font-size:16px;border:1px solid #c7d6cd;border-radius:5px;padding:8px}.hf-toolbar button,.hf-result button,.hf-chip{font:inherit;cursor:pointer;border:1px solid #c7d6cd;border-radius:5px;background:#eef4f0;color:#176d67;min-height:40px;padding:6px 10px}.hf-toolbar button{font-size:13px}.hf-choices{max-height:250px;overflow:auto;overscroll-behavior:contain;padding:0 3px 4px 0}.hf-grade{margin:10px 0 5px;font-size:13px;color:#5e6f63}.hf-options{display:flex;flex-wrap:wrap;gap:5px}.hf-option{display:flex;align-items:center;gap:4px;min-height:36px;padding:5px 7px;border:1px solid #dae3dd;border-radius:5px;font-size:13px;cursor:pointer}.hf-option:has(input:checked){background:#e2f0e8;border-color:#176d67}.hf-option input{accent-color:#176d67;margin:0}.hf-option img{width:15px;height:15px;object-fit:contain}.hf-selected{display:flex;gap:5px;flex-wrap:wrap}.hf-chip{font-size:12px;min-height:32px;padding:4px 7px}.hf-results{margin:8px 0}.hf-results h3{font-size:14px;margin:10px 0 6px}.hf-result{display:flex;gap:7px;align-items:flex-start;justify-content:space-between;border-top:1px solid #e4eae6;padding:7px 0}.hf-result button{font-size:13px;white-space:nowrap;flex:none}.hf-result>div{min-width:0}.hf-result details{font-size:12px;line-height:1.6}.hf-result summary{cursor:pointer;color:#176d67}.hf-result p{font-size:12px;margin:2px 0;color:#5b6c60}.hf-result .pending{color:#875617}.hf-empty{font-size:13px;padding:8px 0}.hf-status{font-size:13px;margin:7px 0}.hf-option[hidden]{display:none!important}@media(max-width:400px){.hf-result{flex-direction:column;gap:2px}}@media print{.hex-filter{display:none}}
'''
JS='''
(()=>{const data=JSON.parse(document.getElementById('hf-data').textContent),selected=new Set(),owned=new Set(),root=document.getElementById('hex-filter'),results=document.getElementById('hf-results'),status=document.getElementById('hf-status'),picked=document.getElementById('hf-selected'),boxes=[...root.querySelectorAll('.hf-choices input[type=checkbox]')],emblems=[...root.querySelectorAll('.hf-emblems input')],onlyOwned=document.getElementById('hf-only-owned');
function n(tag,text,cls){const x=document.createElement(tag);if(text!==undefined)x.textContent=text;if(cls)x.className=cls;return x}
function render(){picked.replaceChildren();for(const [set,bs,prefix] of [[selected,boxes,'海克斯：'],[owned,emblems,'转职：']])for(const name of set){const b=n('button',prefix+name+' ×','hf-chip');b.type='button';b.setAttribute('aria-label','取消 '+name);b.addEventListener('click',()=>{set.delete(name);bs.find(x=>x.value===name).checked=false;render()});picked.append(b)}results.replaceChildren();
const matches=data.comps.filter(c=>[...selected].every(s=>c.hexes[s])&&(!onlyOwned.checked||c.emblemAssociations.some(e=>owned.has(e))));
const ready=[],pending=[];for(const c of matches){const missing=c.conditions.filter(x=>x.type==='hex'?!selected.has(x.name):x.type==='equip'?!owned.has(x.name):true);const relevant=c.emblemOptions.filter(x=>owned.has(x.name));(missing.length?pending:ready).push({c,missing,relevant});}
for(const arr of [ready,pending])arr.sort((a,b)=>a.missing.length-b.missing.length||b.relevant.length-a.relevant.length||(['S','A'].indexOf(a.c.tier)-['S','A'].indexOf(b.c.tier)));
status.textContent='海克斯 '+selected.size+' 项 / 已有转职 '+owned.size+' 项 · 前提满足 '+ready.length+' 套 / 缺条件 '+pending.length+' 套';document.getElementById('hf-summary').textContent='海克斯＋转职筛选'+(selected.size||owned.size?' · 已选 '+(selected.size+owned.size)+' 项':'');
function group(label,arr){if(!arr.length)return;results.append(n('h3',label+' · '+arr.length+'套'));for(const {c,missing,relevant} of arr){const row=n('div',undefined,'hf-result');row.dataset.comp=c.id;row.dataset.ready=String(!missing.length);const b=n('button',c.tier+' · '+c.name);b.type='button';b.addEventListener('click',()=>{document.getElementById('tab'+c.id).click();document.getElementById('c'+c.id).scrollIntoView({block:'start'});});const info=n('div');if(selected.size)info.append(n('p',[...selected].map(s=>s+'：'+c.hexes[s]).join('；')));for(const plan of relevant){const line=n('p');line.append(n('strong',plan.kind+' · '),document.createTextNode(plan.name+' → '+plan.holder+' · '+plan.gain));info.append(line);const fold=n('details');fold.append(n('summary','用法、完整参照盘与代价'));fold.append(n('p',plan.reason),n('p',plan.level+'级：'+plan.board.join('、')),n('p',plan.change+' '+plan.cost),n('p',plan.evidence));info.append(fold);} if(missing.length)info.append(n('p','还缺：'+missing.map(x=>x.name).join('、'),'pending'));else info.append(n('p',c.conditions.length?'已满足所列前置条件；仍需核心来牌与装备。':'无额外前置条件；仍需核心来牌与装备。'));row.append(b,info);results.append(row)}}
group('前置条件已满足',ready);group('缺少前置条件',pending);if(!matches.length)results.append(n('p',onlyOwned.checked&&!owned.size?'请先勾选已有转职；或关闭开关，只按海克斯查阵容。':onlyOwned.checked?'没有同时满足海克斯交集、且与任一已有转职存在已核实关联的阵容。可调整选择或关闭开关；未收录关联不代表该转职绝对不能用。':'没有同时推荐这些海克斯的已收录阵容；可取消一项，不自动改成匹配任意一项。','hf-empty'));
}
onlyOwned.addEventListener('change',render);boxes.forEach(b=>b.addEventListener('change',()=>{b.checked?selected.add(b.value):selected.delete(b.value);render()}));emblems.forEach(b=>b.addEventListener('change',()=>{b.checked?owned.add(b.value):owned.delete(b.value);render()}));document.getElementById('hf-clear').addEventListener('click',()=>{selected.clear();owned.clear();[...boxes,...emblems].forEach(b=>b.checked=false);render()});document.getElementById('hf-search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();root.querySelectorAll('.hf-choices .hf-option').forEach(l=>l.hidden=!l.dataset.name.toLowerCase().includes(q));root.querySelectorAll('.hf-grade-section').forEach(g=>g.hidden=![...g.querySelectorAll('.hf-option')].some(l=>!l.hidden));document.getElementById('hf-no-search').hidden=[...root.querySelectorAll('.hf-choices .hf-option')].some(l=>!l.hidden)});render();})();
'''

def add_filter(html):
 raw=json.loads(re.search(r'<script type="application/json" id="hex-data">(.*?)</script>',html,re.S).group(1));cat=json.loads((P/'catalog.json').read_text())['data'];eq={str(x['id']):x['name'] for x in cat['equip']};hx={str(x['id']):x['name'] for x in cat['hex']};rank=json.loads((P/'rank.json').read_text())['data'];comps=[];pool={};options=build_options()
 for r in rank:
  cid=r['compId']
  if r['tier'] not in ['S','A']:continue
  d=json.loads((P/(cid+'.json')).read_text())['data'];conditions=[]
  for c in d.get('conditions',[]):
   iseq=c['type']=='equip';conditions.append({'type':'equip' if iseq else 'hex','name':(eq if iseq else hx)[str(c['value'])]})
  if cid=='116':conditions.append({'type':'evolution','name':'卡兹克已进化裁决'})
  entries=[x for k,x in raw.items() if k.startswith(cid+'-')];rec={x['name']:x['group'] for x in entries}
  for x in entries:pool.setdefault(x['name'],{'name':x['name'],'icon':x['icon'],'grade':x['grade']})
  comps.append({'id':cid,'name':r['name'],'tier':r['tier'],'hexes':rec,'conditions':conditions,'style':STYLES[cid],'emblemAssociations':[x['name'] for x in options.get(cid,[])],'emblemOptions':options.get(cid,[])})
  pattern=r'(<button[^>]*id="tab'+cid+r'"[^>]*>)(.*?)(</button>)'
  badges='<span class="tab-badges"><span class="tab-style">'+STYLES[cid]+'</span>'+('<span class="tab-condition">'+BADGES[cid]+'</span>' if cid in BADGES else '')+'</span>'
  html,n=re.subn(pattern,lambda m:m[1]+'<span>'+m[2]+'</span>'+badges+m[3],html,count=1,flags=re.S);assert n==1

 groups=[]
 for grade in ['白银','黄金','棱彩','品质未标']:
  items=[x for x in pool.values() if x['grade']==grade]
  if not items:continue
  groups.append('<section class="hf-grade-section"><h3 class="hf-grade">'+grade+'</h3><div class="hf-options">'+''.join('<label class="hf-option" data-name="'+E(x['name'],quote=True)+'"><input type="checkbox" value="'+E(x['name'],quote=True)+'"><img src="'+E(x['icon'],quote=True)+'" alt="" width="15" height="15" referrerpolicy="no-referrer"><span>'+E(x['name'])+'</span></label>' for x in items)+'</div></section>')
 associated_emblems={name for c in comps for name in c['emblemAssociations']}
 emblem_list=list({e['name']:e for e in cat['equip'] if e.get('type')=='转职纹章' and e['name'] in associated_emblems}.values())
 emblem_list.sort(key=lambda e:(e['name'] not in ['永恒之森纹章','迅捷射手纹章','地狱火纹章'],e['name']))
 emblem_html='<h3 class="hf-grade">已有转职（可多选）</h3><details class="hf-emblem-fold"><summary>勾选已拿到的纹章（仅列有推荐阵容的转职）</summary><div class="hf-options hf-emblems">'+''.join('<label class="hf-option"><input type="checkbox" value="'+E(e['name'],quote=True)+'"><img src="'+E(e['picture'],quote=True)+'" alt="" width="15" height="15" referrerpolicy="no-referrer"><span>'+E(e['name'])+'</span></label>' for e in emblem_list)+'</div></details><label class="hf-switch"><input type="checkbox" role="switch" id="hf-only-owned" checked><span>只看能用上已有转职的阵容</span></label><p class="hf-note">开启：转职匹配任意一个，海克斯仍全部匹配。包含必需转职与有明确收益的可选提升；未收录不代表不能用。</p><p class="hf-note">每条方案单独计算：多选转职匹配任意一个，不代表所有方案能同时使用。可选提升不替代必需转职、海克斯或进化条件。</p>'
 panel='<details class="hex-filter" id="hex-filter"><summary id="hf-summary">海克斯＋转职筛选</summary><p class="hf-note">海克斯多选取交集；已有转职匹配必需分支与可选提升，开关控制是否仅看转职关联。满足条件的先列，缺条件的后列；随机纹章或铲子海克斯不代替实际持有转职。</p><div class="hf-selected" id="hf-selected"></div><p class="hf-status" id="hf-status" role="status" aria-live="polite"></p>'+emblem_html+'<h3 class="hf-grade">已选海克斯（可多选）</h3><div class="hf-toolbar"><input type="search" id="hf-search" placeholder="搜索海克斯名称" aria-label="搜索海克斯名称"><button type="button" id="hf-clear">清空已选</button></div><div class="hf-choices">'+''.join(groups)+'<p id="hf-no-search" class="hf-empty" hidden>没有该名称；筛选池仅含这14套阵容推荐的海克斯。</p></div><div class="hf-results" id="hf-results"></div><p class="hf-note">先按前提是否满足，再按缺失条件数、已满足转职与阵容评级排序；“必拿／优先拿／备选”为本攻略机制建议。</p></details>'
 html=html.replace('<div class="tab-list"',panel+'<div class="tab-list"',1)
 payload={'comps':comps,'hexes':list(pool.values())};(P/'hex-filter-audit.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2))
 return html.replace('</style>',CSS+'</style>',1).replace('</body>','<script type="application/json" id="hf-data">'+json.dumps(payload,ensure_ascii=False).replace('<','\\u003c')+'</script><script>'+JS+'</script></body>')
